 function copyWaketimeSchedule() {
   const btn = document.getElementById('copy-waketime-schedule-btn');
   const msg = document.getElementById('copy-waketime-schedule-msg');
   const region = document.getElementById('copy-waketime-schedule-region');
   if (!btn || !msg || !region) return;
   const rows = Array.from(document.querySelectorAll('#waketime-table-body tr'));
   if (!rows.length) return;
   const lines = ['Wake # | Local Time | UTC Time'];
   rows.forEach(row => {
     const cells = Array.from(row.querySelectorAll('td'));
     lines.push(`${cells[0]?.textContent ?? ''} | ${cells[1]?.textContent ?? ''} | ${cells[2]?.textContent ?? ''}`);
   });
   copyToClipboard(lines.join('\n'), msg, region);
 }
+
+// Download stats as JSON file
+function downloadStats() {
+  fetch('stats.json')
+    .then(r => r.json())
+    .then(data => {
+      const jsonStr = JSON.stringify(data);
+      const blob = new Blob([jsonStr], {type: 'application/json'});
+      const url = URL.createObjectURL(blob);
+      const a = document.createElement('a');
+      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
+      a.href = url;
+      a.download = `stats-${timestamp}.json`;
+      a.click();
+      URL.revokeObjectURL(url);
+    });
+}
+document.getElementById('download-stats-btn')?.addEventListener('click', downloadStats);
